set-variable.value:
#[%dw 2.0
output application/java
---
((entriesOf(payload.attachments default {}))
  map (e) -> {
    name: (e.key as String),
    mimeType: ((e.value.^mediaType as String) splitBy ";")[0]
 }) reduce ((item, acc = {}) ->
    acc ++ {
      (item.name as String): {
        mimeType: (item.mimeType as String)
      }
    }
  )]

#[%dw 2.0
output application/java
var att = vars.AttachmentList default {}
var fn  = vars.fileName default {}
var orig = (fn.originalName default "") as String
---
att mapObject ((v, k) ->
  if ((k as String) == orig)
    {(k as String): (v ++ { normalizedName: fn.normalizedName, ruleId: fn.ruleId, fileNamePath: fn.fileNamePath })}
  else
    {(k as String): v}
)]
